import{_ as o,o as t,c as a,a2 as d}from"./chunks/framework.Cdp8-jB6.js";const b=JSON.parse('{"title":"Surface object index — searchable orbit/land list (Mars / Moon / Earth)","description":"","frontmatter":{},"headers":[],"relativePath":"wip/surface-object-index.md","filePath":"wip/surface-object-index.md"}'),s={name:"wip/surface-object-index.md"};function r(i,e,n,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="surface-object-index-—-searchable-orbit-land-list-mars-moon-earth" tabindex="-1">Surface object index — searchable orbit/land list (Mars / Moon / Earth) <a class="header-anchor" href="#surface-object-index-—-searchable-orbit-land-list-mars-moon-earth" aria-label="Permalink to &quot;Surface object index — searchable orbit/land list (Mars / Moon / Earth)&quot;">​</a></h1><p><strong>Status:</strong> implemented (0.7.2), uncommitted. Design note for the searchable index feature added to the three surface routes.</p><h2 id="context-need" tabindex="-1">Context / need <a class="header-anchor" href="#context-need" aria-label="Permalink to &quot;Context / need&quot;">​</a></h2><p>The surface routes (<code>/mars</code>, <code>/moon</code>, <code>/earth</code>, all via <code>SurfaceScene.svelte</code>) let you select an object only by clicking a dot in the 3D scene (or via <code>?site=</code>/<code>?object=</code> deep-links + a screen-reader-only list). There was no visible, searchable way to browse &quot;what&#39;s in orbit and on the ground&quot; for a body. This adds one, modeled on the ISS &quot;modules&quot; UX: a desktop toggle + a mobile drawer tab surfacing a filterable, logo-badged list; a row click flies the camera to the object and opens its detail card.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong>Adapter</strong> — <code>src/lib/surface-map/surface-index.ts</code> (+ <code>.test.ts</code>, 19 cases). Pure <code>toIndexItems(sites, earthObjects, body)</code> normalises the two data shapes (Mars/Moon <code>SurfaceSite</code>; Earth <code>EarthObject</code>) into one <code>IndexItem</code><code>{id, name, agencies[], domain:&#39;orbit&#39;|&#39;land&#39;, category, year, status, regime?, color?, body}</code>, plus <code>filterIndexItems</code> / <code>indexAgencies</code> / <code>indexStatuses</code>.</li><li><strong>Panel</strong> — <code>src/lib/surface-scene/SurfaceIndexPanel.svelte</code>: search box + Domain (orbit/land) · Agency (logo chips) · Era · Status filters + a scrollable row list. Layout-agnostic (fills its container). Reuses <code>matchesQuery</code>, <code>splitAgencies</code>, <code>AgencyBadge</code>; filter model mirrors <code>/fleet</code>.</li><li><strong>Wiring</strong> — <code>SurfaceScene.svelte</code>: a <code>body</code> prop, a reactive <code>indexEarthObjects</code> mirror (the cache is non-reactive), <code>indexItems</code> derived, a desktop left edge-handle + side panel (<code>@media hover:hover and pointer:fine</code>), and an <code>Index</code> <code>MobileDrawerGroup</code> tab. A row calls <code>selectSite(id, { face: true })</code> (camera fly + detail open + URL sync).</li><li>Routes pass <code>body=&quot;mars|moon|earth&quot;</code>.</li></ul><h2 id="key-decisions" tabindex="-1">Key decisions <a class="header-anchor" href="#key-decisions" aria-label="Permalink to &quot;Key decisions&quot;">​</a></h2><ol><li><strong>Year buckets, not launch date</strong> — no <code>launch_date</code> exists in the data (0/85); the filter uses the existing <code>year</code>/<code>launched</code> as era buckets.</li><li><strong>Orbit + land, with an orbit/land filter, on all bodies.</strong> Discovery: Earth already loads <strong>launch sites</strong> (<code>getEarthLaunchSites</code>, on land) alongside satellites (in orbit), so the filter is meaningful on Earth today. Mars/Moon split by <code>kind</code> (surface/orbiter). The <code>domain</code> field in the adapter is the single seam for adding more Earth land-type locations later.</li><li>Master→detail: desktop keeps the list open on select (detail opens right); mobile closes the drawer to reveal the scene.</li></ol><h2 id="notes-future" tabindex="-1">Notes / future <a class="header-anchor" href="#notes-future" aria-label="Permalink to &quot;Notes / future&quot;">​</a></h2><ul><li><strong>i18n</strong>: all 12 new UI strings are translated into the 13 non-en-US locales (in <code>messages/&lt;loc&gt;.json</code>).</li><li><strong>Desktop panel placement</strong>: follows the ISS modules drawer (<code>top:152; left:12; bottom:12; width:min(320px, …)</code>) so it sits UNDER the top-left view controls without overlapping them.</li><li><strong>URL params</strong>: intentionally not added — the index is a transient overlay and selection already syncs via <code>?site=</code>/<code>?object=</code>.</li><li><strong>Earth land-type locations</strong>: the adapter already maps <code>domain:&#39;land&#39;</code>, so future ground locations beyond launch sites slot in with no consumer change.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ul><li>Unit: <code>surface-index.test.ts</code> (adapter + filters). e2e: <code>surface-index.spec.ts</code> (desktop handle → search → row → detail; landscape drawer tab).</li><li>Manual: <code>/mars</code>, <code>/moon</code>, <code>/earth</code> desktop (edge-handle) + landscape (Index tab).</li></ul>',12)])])}const f=o(s,[["render",r]]);export{b as __pageData,f as default};
